  s1_p: "Mande pelo WhatsApp seus planos, preços e dados de pagamento. Nossa equipe monta sua academia na Refka com você, incluindo o app dos alunos com seu logo e suas cores.",
  s1_tag: "Configuração grátis com nossa equipe",
