  faq_q1: "Refka funziona con le tessere e lo scanner che ho già?",
  faq_a1: "Sì. Refka legge le tessere con codice a barre dei Suoi iscritti con un normale scanner USB, e gli iscritti possono entrare anche con il codice QR della loro app. Non deve comprare nuovo hardware.",
  faq_q2: "I soldi dei miei iscritti passano da Refka?",
  faq_a2: "No. Gli iscritti pagano direttamente a Lei, in contanti, con carta o con metodi locali come InstaPay o Vodafone Cash in Egitto. Refka registra ogni pagamento e invia promemoria e link di pagamento, ma non trattiene mai il Suo denaro.",
