  s2_p: "Korzystaj z kart z kodem kreskowym i skanera, które już masz, więc klubowicze zostają przy swoich kartach. Nowi dołączają przez jeden kod QR przy wejściu.",
  s2_tag: "Bez nowego sprzętu",
  s3_t: "Refka sprawia, że wracają",
