  pb_eye: "Rachunek",
  pb_h2: "Refka zarabia na siebie<br>dzięki jednemu lub dwóm klubowiczom.",
  pb_sub: "Starter kosztuje mniej więcej tyle, ile płaci Ci jeden lub dwóch klubowiczów miesięcznie. Zatrzymaj jednego lub dwóch więcej, a Refka już się zwróci. Każdy kolejny klubowicz to zysk.",
  pb_cost: "Refka Starter, miesięcznie", pb_gain: "Klubowicze, którzy przedłużają dzięki Refka", pb_n: "1 do 2",
  faq_eye: "Pytania", faq_h2: "O co pytają nas właściciele klubów",
  faq_q1: "Czy Refka działa z moimi kartami i skanerem?",
  faq_a1: "Tak. Refka odczytuje karty z kodem kreskowym zwykłym skanerem USB, a klubowicze mogą też wchodzić z kodem QR w aplikacji. Nie musisz kupować nowego sprzętu.",
  faq_q2: "Czy pieniądze klubowiczów przechodzą przez Refka?",
  faq_a2: "Nie. Klubowicze płacą bezpośrednio Tobie, gotówką, kartą lub lokalnymi metodami, jak InstaPay czy Vodafone Cash w Egipcie. Refka zapisuje każdą płatność i wysyła przypomnienia oraz linki do płatności, ale nigdy nie przechowuje Twoich pieniędzy.",
  faq_q3: "Czy na recepcji potrzebny jest internet?",
  faq_a3: "Tak. Recepcja działa w przeglądarce i potrzebuje internetu. Wystarczy internet mobilny.",
  faq_q4: "Do kogo należą dane klubu i klubowiczów?",
  faq_a4: "Do Ciebie. Refka używa ich tylko do świadczenia usługi, nigdy ich nie sprzedaje, a Ty możesz je wyeksportować w każdej chwili.",
  faq_q5: "Co się stanie, jeśli przestanę płacić?",
  faq_a5: "Nie ma umowy. Po 7 dniach karencji konto zostaje wstrzymane. Dane klubowiczów przechowujemy 90 dni, żebyś mógł wrócić lub je wyeksportować, a potem je usuwamy.",
  faq_q6: "Kto to konfiguruje i czy jest po polsku?",
  faq_a6: "Nasz zespół konfiguruje klub razem z Tobą przez WhatsApp, bez dodatkowych kosztów. Refka działa w 22 językach, w tym po polsku, dla Ciebie, recepcji i klubowiczów.",
  faq_q7: "Czy mogę przetestować przed zapłatą?",
  faq_a7: "Tak. Masz 30 dni za darmo, ze wszystkimi funkcjami i bez karty kredytowej. Jeśli wybierzesz plan w trakcie testu, pozostałe darmowe dni zostają.",
  faq_more: "Masz inne pytanie?", faq_wa: "Zapytaj nas na WhatsApp", f_contact: "Kontakt"
