  s3_t: "Refka ทำให้พวกเขากลับมา",
  s3_p: "Refka เตือนสมาชิกก่อนหมดอายุ เก็บค่าต่ออายุผ่าน WhatsApp และจับคู่สมาชิกกับเพื่อนออกกำลังกาย คุณติดตามเงินและสมาชิกได้จากมือถือ",
  pb_eye: "คิดง่ายๆ",
