  pb_cost: "Refka Starter ต่อเดือน", pb_gain: "สมาชิกที่ต่ออายุเพราะ Refka", pb_n: "1 ถึง 2",
  faq_eye: "คำถาม", faq_h2: "สิ่งที่เจ้าของยิมถามเรา",
