  oa_q3: "一日中 WhatsApp で支払いを催促している。", oa_b3: "リマインダーは自動で送信", oa_d3: "ジム自身の WhatsApp 番号から、支払いリンク付きで。",
  oa_q4: "受付で現金がなくなる。", oa_b4: "すべての支払いをシフトと担当者にひも付け", oa_d4: "シフト締めでレジを数えます。足りなければ、聞く前に分かります。",
  oa_q5: "会員が辞めても、前兆に気づけない。", oa_b5: "来なくなった会員を把握して、呼び戻す", oa_d5: "Refka は足が遠のいた会員を知らせ、一緒にトレーニングしていた仲間を通じて呼び戻します。",
  oa_f1: "どのスマホでも動作", oa_f2: "スタッフごとに個別ログイン",
  oa_t3: "集金", oa_t5: "レジ",
  oa_collected: "本日の入金", oa_vs: "▲ 先週の同じ曜日より18%増", oa_peak: "ピーク {h}",
  oa_now: "現在ジム内", oa_checkins: "本日の入館", oa_need: "要対応",
  oa_n1: "今週終了する会員権 5件", oa_n1p: "通知済み", oa_n2: "来なくなった会員 9人", oa_n2p: "見る",
  oa_n3: "朝シフトのレジ締め完了", oa_n3p: "一致",
  oa_desk: "受付", oa_scan: "会員カードをスキャン", oa_plan: "月額 · {end}に終了",
