  oa_paid: "支払い済み · {new}まで有効", oa_paid_sub: "{fee} · {m1} · 担当 {s}",
  oa_rem: "リマインダー", oa_auto: "自動", oa_to: "宛先：{w}", oa_from: "ジムの WhatsApp Business 番号から",
  oa_wa_msg: "{wf}さん、会員権があと3日で終了します。ワンタップで更新できます：", oa_wa_rep: "完了しました。今夜行きます 💪",
